const ACLStateManager={removeTermsByCategory(orderedTerms,category,operation=null){return orderedTerms.filter(term=>{if(term.type!=='category'||term.value!==category)return true;return operation?term.operation!==operation:false;});},removeTermsByCommand(orderedTerms,command,operation=null){return orderedTerms.filter(term=>{if(term.type!=='command'||term.value!==command)return true;return operation?term.operation!==operation:false;});},removeTermsByCommands(orderedTerms,commands,operation=null){return orderedTerms.filter(term=>{if(term.type!=='command'||!commands.includes(term.value))return true;return operation?term.operation!==operation:false;});},removeAllCommandAndCategoryTerms(orderedTerms){return orderedTerms.filter(term=>!(term.type==='category'||term.type==='command'));},toggleCategoryState(state,category,operation){if(operation==='grant'){state.grantedCategories.add(category);state.blockedCategories.delete(category);}else if(operation==='block'){state.blockedCategories.add(category);state.grantedCategories.delete(category);}},toggleCommandState(state,command,operation){if(operation==='grant'){state.grantedCommands.add(command);state.blockedCommands.delete(command);}else if(operation==='block'){state.blockedCommands.add(command);state.grantedCommands.delete(command);}},addTerm(orderedTerms,type,operation,value){const existingIndex=orderedTerms.findIndex(term=>term.type===type&&term.operation===operation&&term.value===value);if(existingIndex===-1){orderedTerms.push({type,operation,value});}}};export default ACLStateManager;